+	if !isUnindented(line) {
+		return ""
+	}
+	label := strings.TrimLeft(trimMarkdownEmphasis(strings.TrimSpace(line)), "[")
+	label = strings.ToLower(strings.TrimRight(label, ":*_`] "))
+	for _, marker := range severityMarkers {
+		if label == marker || label == marker+"s" {
+			return label
+		}
+	}
+	return ""
+}
+
+func isUnindented(line string) bool {
+	return line == strings.TrimLeft(line, " \t")
+}
+
+// listItemOrLine returns line without surrounding space and, for a list
+// item, without its bullet.
+func listItemOrLine(line string) string {
+	trimmed := strings.TrimSpace(line)
+	if item, ok := listItemText(trimmed); ok {
+		return item
+	}
+	return trimmed
+}
+
+// isNoFindingsText reports whether text only says a section is empty, such
+// as "None." under a severity heading, so the splitter does not post it.
+func isNoFindingsText(text string) bool {
+	return noFindingsTexts[strings.ToLower(strings.Trim(text, "*_`.!:() \t"))]
+}
+
+var noFindingsTexts = map[string]bool{
+	"": true, "-": true, "—": true, "–": true, "none": true, "n/a": true, "nothing": true,
+	"none found": true, "no issues": true, "no issues found": true, "no findings": true, "nothing to report": true,
+}
+
+// ProseFinding is one top-level finding in prose posted without a usable
+// contract. Severity is its own leading marker or, failing that, the severity
+// label it sits under ("high", "p2"), or "".
+type ProseFinding struct {
+	Text     string
+	Severity string
+}
+
+// SplitProseFindings splits prose into its top-level findings: list items and
+// unindented lines that open with a severity marker, each with the lines that
+// continue it. A line holding only a severity label ("### High", "**Low:**")
+// sets the severity of the findings below it rather than being one, and text
+// under it that is not a list item is a finding too. Any other heading or a
+// placeholder such as "None." ends that, so a closing summary is not posted.
+func SplitProseFindings(prose string) []ProseFinding {
+	var findings []ProseFinding
+	var current strings.Builder
+	group := ""
+	flush := func() {
+		text := strings.TrimSpace(current.String())
+		current.Reset()
+		if text == "" {
+			return
+		}
+		severity := leadingSeverity(text)
+		if severity == "" {
+			severity = group
+		}
+		findings = append(findings, ProseFinding{Text: text, Severity: severity})
+	}
+	for _, line := range strings.Split(strings.TrimSpace(prose), "\n") {
+		if label := severityLabel(line); label != "" {
+			flush()
+			group = label
+			continue
+		}
+		if isUnindented(line) && strings.HasPrefix(line, "#") {
+			flush()
+			group = ""
+			continue
+		}
+		text := listItemOrLine(line)
+		if item, ok := topLevelListItemText(line); ok || (isUnindented(line) && leadingSeverity(line) != "") {
+			flush()
+			if !ok {
+				item = text
+			}
+			if isNoFindingsText(item) {
+				group = ""
+			} else {
+				current.WriteString(item)
+			}
+			continue
+		}
+		if current.Len() == 0 {
+			if group == "" || text == "" {
+				continue
+			}
+			if isNoFindingsText(text) {
+				group = ""
+				continue
+			}
+		} else {
+			current.WriteByte('\n')
+		}
+		current.WriteString(line)
+	}
+	flush()
+	return findings
+}
+
+func topLevelListItemText(line string) (string, bool) {
+	if !isUnindented(line) {
+		return "", false
+	}
+	item, ok := listItemText(strings.TrimSpace(line))
+	return item, ok && item != ""
 }

